#!/usr/bin/env bash
# Regenerates completions/ from globals.go's binName constant — the single
# source of truth for the CLI's name. Run via `mise run completions` after
# renaming the binary there, or whenever a subcommand/flag changes and
# completions need to catch up.
set -euo pipefail
cd "$(dirname "$0")/.."

name=$(sed -n 's/.*const binName = "\(.*\)"/\1/p' globals.go)
fn=${name//-/_}
mkdir -p completions

cat > "completions/${name}.bash" <<EOF
# Bash completion for ${name}. Generated by scripts/gen-completions.sh from
# BINARY_NAME — do not hand-edit the command name here, re-run the generator.
_${fn}_complete() {
    local cur prev subcommands common_flags
    COMPREPLY=()
    cur="\${COMP_WORDS[COMP_CWORD]}"
    prev="\${COMP_WORDS[COMP_CWORD-1]}"
    subcommands="policies flows verdict ui"
    common_flags="--kubeconfig --namespace -n --all-namespaces -A"

    if [[ "\$COMP_CWORD" -eq 1 ]]; then
        COMPREPLY=(\$(compgen -W "\$subcommands" -- "\$cur"))
        return
    fi

    case "\${COMP_WORDS[1]}" in
        policies)
            COMPREPLY=(\$(compgen -W "\$common_flags" -- "\$cur"))
            ;;
        flows)
            COMPREPLY=(\$(compgen -W "\$common_flags --last --follow -f" -- "\$cur"))
            ;;
        verdict)
            if [[ "\$cur" == -* ]]; then
                COMPREPLY=(\$(compgen -W "\$common_flags --last --follow -f --show-unchanged" -- "\$cur"))
            else
                COMPREPLY=(\$(compgen -f -- "\$cur"))
            fi
            ;;
        ui)
            COMPREPLY=(\$(compgen -W "--kubeconfig --addr" -- "\$cur"))
            ;;
    esac
}
complete -F _${fn}_complete ${name}
EOF

cat > "completions/${name}.fish" <<EOF
# Fish completion for ${name}. Generated by scripts/gen-completions.sh from
# BINARY_NAME — do not hand-edit the command name here, re-run the generator.
complete -c ${name} -f -n "__fish_use_subcommand" -a "policies" -d "list live CiliumNetworkPolicy/CCNP state"
complete -c ${name} -f -n "__fish_use_subcommand" -a "flows" -d "stream recent Hubble flows for a namespace"
complete -c ${name} -f -n "__fish_use_subcommand" -a "verdict" -d "diff a candidate policy's verdicts against real flows"
complete -c ${name} -f -n "__fish_use_subcommand" -a "ui" -d "start a local web UI for flows/verdict"

complete -c ${name} -n "__fish_seen_subcommand_from policies flows verdict ui" -l kubeconfig -d "path to kubeconfig"
complete -c ${name} -n "__fish_seen_subcommand_from policies flows verdict" -l namespace -s n -d "namespace to scope the query to"
complete -c ${name} -n "__fish_seen_subcommand_from policies flows verdict" -l all-namespaces -s A -d "query cluster-wide instead of one namespace"
complete -c ${name} -n "__fish_seen_subcommand_from flows verdict" -l last -d "number of flows"
complete -c ${name} -n "__fish_seen_subcommand_from flows verdict" -l follow -s f -d "keep streaming/judging until Ctrl+C"
complete -c ${name} -n "__fish_seen_subcommand_from verdict" -l show-unchanged -d "also print UNCHANGED rows, not just what changed"
complete -c ${name} -n "__fish_seen_subcommand_from verdict" -a "(__fish_complete_suffix .yaml)" -d "candidate policy YAML"
complete -c ${name} -n "__fish_seen_subcommand_from ui" -l addr -d "address to listen on"
EOF

cat > "completions/_${name}" <<EOF
#compdef ${name}
# Zsh completion for ${name}. Generated by scripts/gen-completions.sh from
# BINARY_NAME — do not hand-edit the command name here, re-run the generator.
_${fn}() {
  local -a subcommands
  subcommands=(
    'policies:list live CiliumNetworkPolicy/CCNP state'
    'flows:stream recent Hubble flows for a namespace'
    'verdict:diff a candidate policy'"'"'s verdicts against real flows'
    'ui:start a local web UI for flows/verdict'
  )

  if (( CURRENT == 2 )); then
    _describe 'command' subcommands
    return
  fi

  case "\${words[2]}" in
    policies)
      _arguments '--kubeconfig[path to kubeconfig]:file:_files' '(-n --namespace)'{-n,--namespace}'[namespace]:namespace:' '(-A --all-namespaces)'{-A,--all-namespaces}'[query cluster-wide]'
      ;;
    flows)
      _arguments '--kubeconfig[path to kubeconfig]:file:_files' '(-n --namespace)'{-n,--namespace}'[namespace]:namespace:' '(-A --all-namespaces)'{-A,--all-namespaces}'[query cluster-wide]' '--last[number of flows]:count:' '(-f --follow)'{-f,--follow}'[keep streaming until Ctrl+C]'
      ;;
    verdict)
      _arguments '--kubeconfig[path to kubeconfig]:file:_files' '(-n --namespace)'{-n,--namespace}'[namespace]:namespace:' '(-A --all-namespaces)'{-A,--all-namespaces}'[query cluster-wide]' '--last[number of flows to sample]:count:' '(-f --follow)'{-f,--follow}'[keep judging until Ctrl+C]' '--show-unchanged[also print UNCHANGED rows]' '*:candidate policy YAML:_files -g "*.yaml"'
      ;;
    ui)
      _arguments '--kubeconfig[path to kubeconfig]:file:_files' '--addr[address to listen on]:address:'
      ;;
  esac
}
_${fn} "\$@"
EOF

echo "Generated completions for '${name}' in completions/"
